class MountainBlendTest{public static void main(String[]a){int previous=-1;boolean mixed=false;for(double exposure:new double[]{0,.25,.4,.525,.65,.8,1}){int rock=0,soil=0,grass=0;for(int z=0;z<128;z++)for(int x=0;x<128;x++){int m=OrganicMaterials.mountainMaterial(exposure,.5,.5,x,z,73,80/110.);if(m==1)grass++;else if(m==7||m==10)soil++;else rock++;}if(rock<previous)throw new AssertionError("Rock coverage does not increase gradually");if(rock>1000&&grass>1000&&soil>100)mixed=true;previous=rock;}if(!mixed)throw new AssertionError("No mixed grass / soil / rock transition");System.out.println("PASS: transition contains interleaved grass, gravel/coarse dirt and rock; rock coverage increases gradually with exposure");}}
